def c_autoajuste_mitad(P, ctx, mod):
    aj = float(ctx.get("ajuste") or 1.0)
    if abs(aj - 1.0) < 1e-4:
        return None
    nuevo = round(1.0 + 0.5 * (aj - 1.0), 3)
    ctx["ajuste"] = nuevo
    return P, ctx, {"ajuste": nuevo}

def c_sin_autoajuste_sesgo50_dia3(P, ctx, mod):
    ctx["ajuste"] = 1.0
    ph = (mod.get("aciertos") or {}).get("por_horizonte") or {}
    pts = [(0, 0.0)]
    for h, v in ph.items():
        if (v.get("n") or 0) >= 30 and v.get("sesgo_m") is not None:
            pts.append((int(h), float(v["sesgo_m"])))
    pts.sort()
    if len(pts) < 3:
        return None
    def s(t):
        for (h0, v0), (h1, v1) in zip(pts, pts[1:]):
            if t <= h1:
                return v0 + (v1 - v0) * (t - h0) / (h1 - h0)
        return pts[-1][1]
    c = mod.get("curva_mazar") or {"a": 3.6595, "b": 0.12497}
    dvdz = c["a"] + c["b"] * max(0.0, float(ctx["cota"]) - 2115.0)
    k = dvdz / 0.0864
    corr = [0.0 if d < 2 else max(-80.0, min(80.0, -(s(d + 1) - s(d)) * k * 0.5)) for d in range(60)]
    base = list(ctx.get("memoria") or [])
    n = max(len(base), len(corr))
    out = [round((base[i] if i < len(base) else 0.0) + (corr[i] if i < len(corr) else 0.0), 2) for i in range(n)]
    ctx["memoria"] = out
    return P, ctx, {"ajuste": 1.0, "memoria": out}

def c_sin_autoajuste_cortes_7d(P, ctx, mod):
    plan = list(ctx.get("cutPlan") or [])
    hoy = plan[0] if plan and isinstance(plan[0], (int, float)) and not isinstance(plan[0], bool) else None
    if not hoy:
        return None
    plan = plan + [None] * max(0, 8 - len(plan))
    for d in range(1, 8):
        if plan[d] is None:
            plan[d] = hoy
    ctx["ajuste"] = 1.0
    ctx["cutPlan"] = plan
    return P, ctx, {"ajuste": 1.0, "cutPlan": plan}
